		writeJSON(w, status, body)
		s.log.Request("GET /v1/accounts", "", fmt.Sprintf("http=%d", status), s.now().Sub(start))
		return
	}
	summaries := make([]AccountSummary, 0, len(accounts))
	for _, account := range accounts {
