/**
 * TransactionSourceRepository tests (T013; FR-005/006, SC-009): persistence,
 * uniqueness pre-check + index backstop, and survival across an app restart.
 */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34])
class SourceRepositoryTest {

    private lateinit var db: AppDatabase
    private lateinit var repository: TransactionSourceRepository

    @Before
    fun setUp() {
        val context = ApplicationProvider.getApplicationContext<Context>()
        db = Room.inMemoryDatabaseBuilder(context, AppDatabase::class.java)
            .allowMainThreadQueries()
            .build()
        repository = TransactionSourceRepository(db.transactionSourceDao(), db.parseErrorDao())
    }

    @After
    fun tearDown() {
        db.close()
    }

    private fun source(id: String = UUID.randomUUID().toString(), name: String = "Example Bank") = TransactionSource(
        id = id,
        name = name,
        identifier = "com.example.bank",
        channel = "notification",
        enabled = true,
        template = "خرید مبلغ {amount} ریال {direction}",
        incomeKeywords = "واریز",
        expenseKeywords = "خرید",
        createdAt = "2026-09-24T00:00:00+03:30",
        updatedAt = "2026-09-24T00:00:00+03:30",
    )

    @Test
    fun `a valid source is persisted and lists as a flow`() = runTest {
        assertEquals(SaveResult.Saved, repository.save(source()))
        assertEquals(1, repository.all().size)
        assertEquals(1, repository.enabled().size)
        assertEquals("Example Bank", repository.all().first().name)
    }

    @Test
    fun `invalid source is rejected without persisting`() = runTest {
        val result = repository.save(source(name = "  "))
        assertTrue(result is SaveResult.Invalid)
        assertEquals(0, repository.all().size)
    }

    @Test
    fun `duplicate identifier and channel is blocked naming the conflict`() = runTest {
        repository.save(source(id = "existing", name = "Old Bank"))
        val result = repository.save(source(id = "new", name = "New Bank"))

        assertTrue(result is SaveResult.Invalid)
        val error = (result as SaveResult.Invalid).errors.first { it.field == "identifier" }
        assertTrue(error.message.contains("Old Bank"))
        assertEquals(1, repository.all().size)
    }

    @Test
    fun `editing an existing source updates it in place`() = runTest {
        repository.save(source(id = "src-1"))
        assertEquals(SaveResult.Saved, repository.save(source(id = "src-1", name = "Renamed")))
        assertEquals(1, repository.all().size)
        assertEquals("Renamed", repository.byId("src-1")?.name)
    }

    @Test
    fun `resolve finds a source by identifier and channel`() = runTest {
        repository.save(source())
        assertEquals(
            "Example Bank",
            repository.resolve("com.example.bank", com.gomoney.capture.model.Channel.NOTIFICATION)?.name,
        )
        assertEquals(
            null,
            repository.resolve("com.example.bank", com.gomoney.capture.model.Channel.SMS),
        )
    }

    /** FR-006: definitions survive app/device restart (file-backed database). */
    @Test
    fun `definitions survive a database restart`() = runTest {
        val context = ApplicationProvider.getApplicationContext<Context>()
        val name = "source-restart-${UUID.randomUUID()}.db"

        val first = Room.databaseBuilder(context, AppDatabase::class.java, name)
            .allowMainThreadQueries()
            .build()
        try {
            TransactionSourceRepository(first.transactionSourceDao(), first.parseErrorDao())
                .save(source(id = "persisted", name = "Persisted Bank"))
        } finally {
            first.close()
        }

    private fun pipeline() = CapturePipeline(
        db = db,
        settings = SettingsRepository(ApplicationProvider.getApplicationContext()) {
            ApplicationProvider.getApplicationContext<Context>().getSharedPreferences("t", Context.MODE_PRIVATE)
        },
        deliveryRepository = deliveryRepository,
        dedupRepository = dedupRepository,
    )

    private fun rawEvent(id: String, source: String, sourcePackage: String, postedAt: String): RawEvent = RawEvent(
        id = id,
        source = source,
        sourcePackage = sourcePackage,
        bank = null,
        title = if (source == "notification") "بانک ملت" else null,
        text = mellatText,
        postedAt = postedAt,
        capturedAt = postedAt,
    )


    private suspend fun configure() {
        val settings = SettingsRepository(ApplicationProvider.getApplicationContext()) {
            ApplicationProvider.getApplicationContext<Context>().getSharedPreferences("t", Context.MODE_PRIVATE)
        }
        settings.setEnabledBankPackages(setOf("ir.mellat.mellatab", "MELLAT"))
        settings.setNotificationCaptureEnabled(true)
        settings.setSmsCaptureEnabled(true)
        settings.setServerUrl("http://192.168.1.10:8787")
        settings.setBearerToken("test-token")
    }

    /** Same real transaction, SMS 28 s later (same minute) → exact fingerprint → local short-circuit. */
    @Test
    fun `same minute notification and sms collapse locally`() = runTest {
        configure()
        val pipeline = pipeline()

        val notification = rawEvent("evt-notif", "notification", "ir.mellat.mellatab", "2026-09-23T20:31:22+03:30")
        val sms = rawEvent("evt-sms", "sms", "MELLAT", "2026-09-23T20:31:50+03:30")

        val first = pipeline.process(notification)
        val second = pipeline.process(sms)

        assertEquals(Outcome.QUEUED, first)
        // Identical fingerprint (same round(ts), same bank/account/type/amount/description).
        assertEquals(Outcome.DUPLICATE_SHORT_CIRCUITED, second)
        assertEquals(1, db.normalizedTransactionDao().count())
    }

    /** Cross-minute (≤2 min) pair: both queue locally; bridge collapses via bucket window. */
    @Test
    fun `cross minute pair queues both and fingerprints differ only by minute`() = runTest {
        configure()
        val pipeline = pipeline()

        val notification = rawEvent("evt-notif2", "notification", "ir.mellat.mellatab", "2026-09-23T20:31:22+03:30")
        val sms = rawEvent("evt-sms2", "sms", "MELLAT", "2026-09-23T20:32:30+03:30") // 68 s later

        val first = pipeline.process(notification)
        val second = pipeline.process(sms)

        assertEquals(Outcome.QUEUED, first)
        assertEquals(Outcome.QUEUED, second)
        assertEquals(2, db.normalizedTransactionDao().count())

        // The two rows differ only in the minute-rounded fingerprint component;
        // the bridge's ±2-min window scan (adjacent buckets) collapses them —
        // exactly one Go Money transaction (FR-030, verified in Go tests).
        val parsed = db.normalizedTransactionDao().observeRecent(10).first()
        val fingerprints = parsed.map { it.fingerprint }
        assertEquals(2, fingerprints.distinct().size)
        fingerprints.forEach { fp ->
            assertEquals(64, fp.length)
        }
    }

    /** SMS capture disabled → ignored entirely (US5 scenario 2, FR-017). */
    @Test
    fun `sms when capture disabled is ignored`() = runTest {
        val pipeline = pipeline()
        // smsCaptureEnabled defaults to false.
        val sms = rawEvent("evt-sms-off", "sms", "MELLAT", "2026-09-23T20:31:22+03:30")

        val outcome = pipeline.process(sms)
        assertEquals(Outcome.IGNORED_DISABLED, outcome)
        assertEquals(0, db.normalizedTransactionDao().count())
    }
}

