@Query(
    """DELETE FROM delivery_records
        WHERE state = 'sent'
            AND id NOT IN (
                SELECT id FROM normalized_transactions
                WHERE memoSyncState = 'pending' OR assignmentSyncState = 'pending'
            )""",
)
suspend fun clearSent(): Int

