// isLettersDigits accepts ISO-like currency codes: 1–16 letters/digits.
func isLettersDigits(s string) bool {
	for _, r := range s {
		isLetter := (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
		isDigit := r >= '0' && r <= '9'
		if !isLetter && !isDigit {
			return false
		}
	}
	return len(s) > 0
}

