package com.gomoney.capture.model

/**
 * Notification-engine enums (data-model.md §1/§7, contracts/source-template.md).
 */

/** How a user-defined source receives messages. */
enum class Channel {
    NOTIFICATION,
    SMS;

    /** Lowercase wire value stored in Room and compared against RawEvent.source. */
    val wire: String get() = name.lowercase()

    companion object {
        fun wire(value: String): Channel? =
            entries.firstOrNull { it.name.equals(value, ignoreCase = true) }

        fun fromEventSource(source: EventSource): Channel = when (source) {
            EventSource.NOTIFICATION -> NOTIFICATION
            EventSource.SMS -> SMS
        }
    }
}

/** Resolved transaction direction for a user-source capture. */
enum class Direction {
    INCOME,
    EXPENSE;

    val wire: String get() = name.lowercase()
}

/** Assignment sync state for a captured transaction's destination/category. */
enum class AssignmentSyncState {
    PENDING,
    SYNCED;

    val wire: String get() = name.lowercase()

    companion object {
        fun wire(value: String): AssignmentSyncState? =
            entries.firstOrNull { it.name.equals(value, ignoreCase = true) }
    }
}
package com.gomoney.capture.model

/**
 * Error taxonomy (FR-023, research.md R9) — exactly six categories.
 */
enum class ErrorCategory {
    CAPTURE_ERROR,
    PARSE_ERROR,
    VALIDATION_ERROR,
    NETWORK_ERROR,
    SERVER_ERROR,
    DUPLICATE,
}

/** Capture source kinds (data-model.md §1). */
enum class EventSource {
    NOTIFICATION,
    SMS;

    companion object {
        fun wire(value: String): EventSource? =
            entries.firstOrNull { it.name.equals(value, ignoreCase = true) }
    }
}

/** Normalized transaction kinds. */
enum class TxType {
    EXPENSE,
    INCOME;

    companion object {
        fun wire(value: String): TxType? =
            entries.firstOrNull { it.name.equals(value, ignoreCase = true) }
    }
}

/** Delivery lifecycle states (data-model.md §3) — single terminal success `SENT`. */
enum class DeliveryState {
    CAPTURED,
    PARSED,
    QUEUED,
    SENDING,
    SENT,
    FAILED,
}

/** How sure a parser is about a parse result. */
enum class Confidence {
    HIGH,
    MEDIUM,
    LOW,
}

package com.gomoney.capture.capture

import com.gomoney.capture.logging.Redactor
import com.gomoney.capture.model.DeliveryState
import com.gomoney.capture.model.EventSource
import com.gomoney.capture.parser.Fingerprint
import com.gomoney.capture.parser.ParserRegistry
import com.gomoney.capture.parser.ParseResult
import com.gomoney.capture.storage.AppDatabase
import com.gomoney.capture.storage.DedupRepository
import com.gomoney.capture.storage.DeliveryRepository
import com.gomoney.capture.storage.NormalizedTransaction
import com.gomoney.capture.storage.RawEvent
import com.gomoney.capture.storage.ServerConfiguration
import com.gomoney.capture.storage.SettingsRepository
import com.gomoney.capture.storage.eventSource
import com.gomoney.capture.storage.txType
import java.util.UUID

/**
 * Capture pipeline (US1, T020):
 * RawEvent → allow-list gate → ParserRegistry selection → parse →
 * fingerprint → persist NormalizedTransaction + DeliveryRecord(queued)
 * transactionally. No parser match → RawEvent retained flagged parse_error
 * (US6 scenario 2 — never silently dropped).
 */
class CapturePipeline(
    private val db: AppDatabase,
    private val settings: SettingsRepository,
    private val registry: ParserRegistry = ParserRegistry(),
    private val deliveryRepository: DeliveryRepository,
    private val dedupRepository: DedupRepository,
    private val onCaptured: suspend (NormalizedTransaction) -> Unit = {},
    // --- notification-engine (US1/US2/US4) ---
    private val sourceRepository: com.gomoney.capture.source.TransactionSourceRepository? = null,
    private val userSourceParser: com.gomoney.capture.source.UserSourceParser? = null,
) {

    /**
     * Process one captured event. Raw text is persisted BEFORE any processing
     * (FR-002) and never logged (FR-028).
     */
    suspend fun process(event: RawEvent): Outcome {
        val config = settings.current()

        // Capture source toggle (spec scenario 1.3: disabled → capture nothing).
        if (event.eventSource() == EventSource.NOTIFICATION && !config.notificationCaptureEnabled) {
            return Outcome.IGNORED_DISABLED
        }
        if (event.eventSource() == EventSource.SMS && !config.smsCaptureEnabled) {
            return Outcome.IGNORED_DISABLED
        }

        // User-defined sources are the most specific intent for an identifier
        // and are checked first (research R3, FR-004/024). Disabled sources are
        // skipped and removed sources are simply absent (US4).
        val userSource = sourceRepository?.resolve(
            event.sourcePackage,
            com.gomoney.capture.model.Channel.fromEventSource(event.eventSource()),
        )
        if (userSource != null && userSource.enabled && userSourceParser != null) {
            return processUserSource(event, userSource)
        }

        // Allow-list gate (FR-001): ignore every other app silently.
        if (event.sourcePackage !in config.enabledBankPackages) {
            return Outcome.IGNORED_NOT_ALLOW_LISTED
        }

        // FR-002: persist the raw event before ANY processing.
        db.rawEventDao().insert(event)

        val parser = registry.select(event)
        if (parser == null) {
            // Retained, flagged parse_error (US6 scenario 2).
            deliveryRepository.createParseError(
                id = event.id,
                sourceEventId = event.id,
                reason = "no parser claims this source",
            )
            return Outcome.RETAINED_PARSE_ERROR
        }

        val result = parser.parse(event)
        val parsed = when (result) {
            is ParseResult.Success -> result.transaction
            is ParseResult.Failure -> {
                deliveryRepository.createParseError(
                    id = event.id,
                    sourceEventId = event.id,
                    reason = Redactor.safeDetail(result.reason), // sanitized only
                )
                return Outcome.RETAINED_PARSE_ERROR
            }
        }

        // Fingerprint computed by the pipeline (parser-interface.md rule 4).
        val fingerprint = Fingerprint.compute(
            bank = parsed.bank,
            accountHint = parsed.accountHint,
            type = parsed.txType(),
            amountMinor = parsed.amountMinor,
            txAt = parsed.txAt,
            description = parsed.description,
        )

        // Local short-circuit: a re-captured identical event (or known
        // duplicate after restart) is queued as already-terminal (US3).
        val known = dedupRepository.lookup(fingerprint)

        val finalTx = parsed.copy(
            id = UUID.randomUUID().toString(),
            fingerprint = fingerprint,
        )

        return persist(finalTx, event, known)
    }

    private suspend fun processUserSource(
        event: RawEvent,
        source: com.gomoney.capture.storage.TransactionSource,
    ): Outcome {
        // FR-002: persist the raw event before matching so a failure can be
        // retained and reviewed (FR-010).
        db.rawEventDao().insert(event)

        val result = userSourceParser!!.parse(event, source)
        val parsed = when (result) {
            is ParseResult.Success -> result.transaction
            is ParseResult.Failure -> {
                // The ParseErrorMessage is retained by UserSourceParser; the
                // outbox parse error keeps the existing events-screen behaviour.
                deliveryRepository.createParseError(
                    id = event.id,
                    sourceEventId = event.id,
                    reason = Redactor.safeDetail(result.reason),
                )
                return Outcome.RETAINED_PARSE_ERROR
            }
        }

        val fingerprint = Fingerprint.compute(
            bank = parsed.bank,
            accountHint = parsed.accountHint,
            type = parsed.txType(),
            amountMinor = parsed.amountMinor,
            txAt = parsed.txAt,
            description = parsed.description,
        )
        val known = dedupRepository.lookup(fingerprint)
        val finalTx = parsed.copy(id = UUID.randomUUID().toString(), fingerprint = fingerprint)
        return persist(finalTx, event, known)
    }

    private suspend fun persist(
        tx: NormalizedTransaction,
        event: RawEvent,
        knownOutcome: com.gomoney.capture.storage.DedupCache?,
    ): Outcome {
        // The unique fingerprint index guards against cross-source duplicates
        // that share an exact fingerprint (same source duplicate → identical
        // fingerprint). If the row already exists locally this is a duplicate
        // capture: short-circuit instead of corrupting state.
        val inserted = db.normalizedTransactionDao().insert(tx)
        if (inserted == -1L) {
            // Fingerprint already stored — mark the raw event's delivery row
            // as duplicate-acked (terminal) so it is not re-delivered.
            deliveryRepository.markDuplicateAcked(event.id, "exact duplicate of existing capture")
            return Outcome.DUPLICATE_SHORT_CIRCUITED
        }

        if (knownOutcome != null) {
            // Locally known terminal duplicate — queue is unnecessary.
            db.deliveryRecordDao().insert(
                com.gomoney.capture.storage.DeliveryRecord(
                    id = tx.id,
                    state = DeliveryState.SENT.name.lowercase(),
                    attempts = 0,
                    lastAttemptAt = null,
                    nextRetryAt = null,
                    errorCategory = com.gomoney.capture.model.ErrorCategory.DUPLICATE.name.lowercase(),
                    errorDetail = "locally known ${knownOutcome.outcome}",
                    sourceEventId = event.id,
                ),
            )
            return Outcome.QUEUED_AS_KNOWN_DUPLICATE
        }

        deliveryRepository.createQueued(id = tx.id, sourceEventId = event.id)
        onCaptured(tx) // triggers the expedited sync enqueue (T031)
        return Outcome.QUEUED
    }
}

enum class Outcome {
    QUEUED,
    QUEUED_AS_KNOWN_DUPLICATE,
    DUPLICATE_SHORT_CIRCUITED,
    RETAINED_PARSE_ERROR,
    IGNORED_DISABLED,
    IGNORED_NOT_ALLOW_LISTED,
}
package com.gomoney.capture.source

import com.gomoney.capture.logging.Redactor
import com.gomoney.capture.model.Confidence
import com.gomoney.capture.parser.BankParser
import com.gomoney.capture.parser.ParseResult
import com.gomoney.capture.storage.NormalizedTransaction
import com.gomoney.capture.storage.ParseErrorMessage
import com.gomoney.capture.storage.RawEvent
import com.gomoney.capture.storage.TransactionSource
import java.time.OffsetDateTime
import java.util.UUID

/**
 * User-source capture parser (contracts/source-template.md, T021): matches a
 * message against the source's template and produces a NormalizedTransaction
 * that flows through the existing fingerprint/queue/delivery path unchanged
 * (FR-022). On failure it retains a sanitized [ParseErrorMessage] (FR-010) and
 * returns [ParseResult.Failure] so the pipeline records the outbox parse error.
 *
 * Raw message text never leaves this class except into the local RawEvent
 * reference; only a normalized description is produced.
 */
class UserSourceParser(
    private val parseErrorRepository: ParseErrorRepository,
    private val clock: () -> OffsetDateTime = { OffsetDateTime.now() },
) {

    suspend fun parse(event: RawEvent, source: TransactionSource): ParseResult {
        val compiled = runCatching { TemplateMatcher.compile(source.template) }
            .getOrElse { return fail(event, source, "invalid template") }

        return when (val result = TemplateMatcher.match(compiled, event.text, source)) {
            is MatchResult.Success -> ParseResult.Success(
                NormalizedTransaction(
                    id = "",
                    sourceEventId = event.id,
                    source = event.source,
                    bank = USER_BANK,
                    accountHint = source.identifier,
                    type = result.direction.wire,
                    amountMinor = result.amountMinor,
                    currency = "IRR",
                    txAt = event.postedAt,
                    description = BankParser.cleanDescription(event),
                    rawTextRef = event.id,
                    fingerprint = "",
                    parserName = PARSER_NAME,
                    confidence = Confidence.HIGH.name,
                    sourceId = source.id,
                    accountId = source.boundAccountId, // FR-015
                ),
            )

            is MatchResult.Failure -> fail(event, source, result.reason)
        }
    }

    private suspend fun fail(event: RawEvent, source: TransactionSource, reason: String): ParseResult {
        val sanitized = Redactor.safeDetail(reason) // never raw text (FR-023)
        parseErrorRepository.insert(
            ParseErrorMessage(
                id = UUID.randomUUID().toString(),
                sourceId = source.id,
                sourceEventId = event.id,
                failureReason = sanitized,
                occurredAt = clock().toString(),
            ),
        )
        return ParseResult.Failure(sanitized, Confidence.MEDIUM)
    }

    companion object {
        const val PARSER_NAME = "UserSourceParser"

        /** Stable slug for user-source transactions so fingerprints stay uniform. */
        const val USER_BANK = "user"
    }
}

