package com.gomoney.capture.storage

import com.gomoney.capture.model.DeliveryState
import com.gomoney.capture.model.ErrorCategory
import java.time.OffsetDateTime

/** DeliveryState accessor outside Room's field processing. */
fun DeliveryRecord.deliveryStateOf(): DeliveryState =
    DeliveryState.entries.firstOrNull { it.name.equals(state, ignoreCase = true) } ?: DeliveryState.CAPTURED

/**
 * Delivery state machine helpers (data-model.md §3):
 * CAPTURED → PARSED → QUEUED → SENDING → SENT (terminal) and
 * SENDING → FAILED → QUEUED on retry. All transitions are transactional.
 */
class DeliveryRepository(
    private val deliveryRecordDao: DeliveryRecordDao,
    private val clock: () -> OffsetDateTime = { OffsetDateTime.now() },
) {

    /** Legal forward transitions (state → state). */
    private val legalTransitions: Map<DeliveryState, Set<DeliveryState>> = mapOf(
        DeliveryState.CAPTURED to setOf(DeliveryState.PARSED),
        DeliveryState.PARSED to setOf(DeliveryState.QUEUED),
        DeliveryState.QUEUED to setOf(DeliveryState.SENDING),
        DeliveryState.SENDING to setOf(DeliveryState.SENT, DeliveryState.FAILED),
        DeliveryState.FAILED to setOf(DeliveryState.QUEUED),
        DeliveryState.SENT to emptySet(), // terminal & immutable
    )

    /** Create the initial outbox row for a parsed transaction. */
    suspend fun createQueued(id: String, sourceEventId: String): DeliveryRecord {
        val record = DeliveryRecord(
            id = id,
            state = DeliveryState.QUEUED.name.lowercase(),
            attempts = 0,
            lastAttemptAt = null,
            nextRetryAt = null,
            errorCategory = null,
            errorDetail = null,
            sourceEventId = sourceEventId,
        )
        deliveryRecordDao.insert(record)
        return record
    }

    /** Create a retained parse-error row (US6 scenario 2 — never silently dropped). */
    suspend fun createParseError(id: String, sourceEventId: String, reason: String): DeliveryRecord {
        val record = DeliveryRecord(
            id = id,
            state = DeliveryState.PARSED.name.lowercase(),
            attempts = 0,
            lastAttemptAt = null,
            nextRetryAt = null,
            errorCategory = ErrorCategory.PARSE_ERROR.name.lowercase(),
            errorDetail = reason,
            sourceEventId = sourceEventId,
        )
        deliveryRecordDao.insert(record)
        return record
    }

    /**
     * Apply a state transition, validating legality. Illegal transitions are
     * rejected (return null) rather than corrupting the outbox.
     */
    suspend fun transition(
        id: String,
        to: DeliveryState,
        errorCategory: ErrorCategory? = null,
        errorDetail: String? = null,
    ): DeliveryRecord? {
        val current = deliveryRecordDao.byId(id) ?: return null
        val from = current.deliveryStateOf()

        if (to !in legalTransitions[from].orEmpty()) {
            return null // illegal — SENT is terminal and immutable (§3)
        }
        if (to == DeliveryState.FAILED && errorCategory == null) {
            return null // FAILED requires a non-null category (§3 rules)
        }
        if (from == DeliveryState.SENT) {
            return null
        }

        val now = clock()
        val updated = current.copy(
            state = to.name.lowercase(),
            attempts = if (to == DeliveryState.SENDING) current.attempts + 1 else current.attempts,
            lastAttemptAt = if (to == DeliveryState.SENDING || to == DeliveryState.SENT || to == DeliveryState.FAILED) {
                now.toString()
            } else {
                current.lastAttemptAt
            },
            errorCategory = errorCategory?.name?.lowercase() ?: current.errorCategory,
            errorDetail = errorDetail ?: current.errorDetail,
        )
        deliveryRecordDao.upsert(updated)
        return updated
    }

    /**
     * Duplicate acknowledgement is terminal: state=sent with
     * errorCategory=duplicate (already recorded in Go Money — §3 rules).
     */
    suspend fun markDuplicateAcked(id: String, detail: String? = null): DeliveryRecord? {
        val current = deliveryRecordDao.byId(id) ?: return null
        if (current.deliveryStateOf() == DeliveryState.SENT) return current
        val updated = current.copy(
            state = DeliveryState.SENT.name.lowercase(),
            lastAttemptAt = clock().toString(),
            errorCategory = ErrorCategory.DUPLICATE.name.lowercase(),
            errorDetail = detail,
        )
        deliveryRecordDao.upsert(updated)
        return updated
    }

    /** Manual/auto retry: FAILED → QUEUED (§3 diagram). */
    suspend fun requeue(id: String, nextRetryAt: OffsetDateTime? = null): DeliveryRecord? {
        val current = deliveryRecordDao.byId(id) ?: return null
        if (current.deliveryStateOf() != DeliveryState.FAILED) return null
        val updated = current.copy(
            state = DeliveryState.QUEUED.name.lowercase(),
            nextRetryAt = nextRetryAt?.toString(),
        )
        deliveryRecordDao.upsert(updated)
        return updated
    }
}

package com.gomoney.capture.source

import android.database.sqlite.SQLiteConstraintException
import com.gomoney.capture.model.Channel
import com.gomoney.capture.storage.ParseErrorDao
import com.gomoney.capture.storage.TransactionSource
import com.gomoney.capture.storage.TransactionSourceDao
import java.time.OffsetDateTime
import kotlinx.coroutines.flow.Flow

/** Outcome of a save attempt. */
sealed interface SaveResult {
    data object Saved : SaveResult

    data class Invalid(val errors: List<ValidationError>) : SaveResult
}

/**
 * Persistence for user-defined sources (FR-001/002/003/005/006, US4). Saving
 * pre-validates via [SourceValidator] and relies on the `(identifier, channel)`
 * unique index as the race backstop (SC-009).
 */
class TransactionSourceRepository(
    private val sourceDao: TransactionSourceDao,
    private val parseErrorDao: ParseErrorDao,
    private val clock: () -> OffsetDateTime = { OffsetDateTime.now() },
) {

    fun observeAll(): Flow<List<TransactionSource>> = sourceDao.observeAll()

    suspend fun all(): List<TransactionSource> = sourceDao.all()

    suspend fun enabled(): List<TransactionSource> = sourceDao.enabled()

    suspend fun byId(id: String): TransactionSource? = sourceDao.byId(id)

    /** Resolve the source for an event's identifier + channel (enabled or not). */
    suspend fun resolve(identifier: String, channel: Channel): TransactionSource? =
        sourceDao.byIdentifierAndChannel(identifier, channel.wire)

    /** Uniqueness pre-check hook used by the editor before saving (FR-005). */
    suspend fun validateForSave(source: TransactionSource): List<ValidationError> =
        SourceValidator.validate(source, sourceDao.all())

    suspend fun save(source: TransactionSource): SaveResult {
        val errors = validateForSave(source)
        if (errors.isNotEmpty()) return SaveResult.Invalid(errors)

        val now = clock().toString()
        val existing = sourceDao.byId(source.id)
        val toStore = source.copy(
            name = source.name.trim(),
            identifier = source.identifier.trim(),
            createdAt = existing?.createdAt ?: source.createdAt.ifBlank { now },
            updatedAt = now,
        )
        return try {
            if (existing == null) {
                sourceDao.insert(toStore)
            } else {
                sourceDao.update(toStore)
            }
            SaveResult.Saved
        } catch (conflict: SQLiteConstraintException) {
            SaveResult.Invalid(
                listOf(
                    ValidationError(
                        "identifier",
                        "Identifier and channel are already used by another source",
                    ),
                ),
            )
        }
    }

    /** Enable/disable without deleting (FR-003, US4.1/US4.2). */
    suspend fun setEnabled(id: String, enabled: Boolean): Boolean =
        sourceDao.setEnabled(id, enabled, clock().toString()) > 0

    /**
     * Remove the source row, keep already-captured transactions, and null the
     * parse-error reference so the review list survives (US4.3, FR-003).
     */
    suspend fun remove(id: String): Boolean {
        val deleted = sourceDao.deleteById(id)
        parseErrorDao.clearSource(id)
        return deleted > 0
    }
}

package com.gomoney.capture.source

import com.gomoney.capture.model.Channel
import com.gomoney.capture.storage.TransactionSource
import com.gomoney.capture.storage.keywordList

/** One user-facing source validation failure (contracts/source-template.md). */
data class ValidationError(val field: String, val message: String)

/**
 * Source validation contract (FR-005/012, SC-009): non-blank name/identifier,
 * a template with exactly one `{direction}` and one `{amount}`, non-empty
 * income/expense keyword lists, and no other source sharing the same
 * `(identifier, channel)`.
 */
object SourceValidator {

    const val MAX_NAME_LENGTH = 100

    fun validate(source: TransactionSource, existing: List<TransactionSource>): List<ValidationError> {
        val errors = mutableListOf<ValidationError>()

        val name = source.name.trim()
        if (name.isEmpty()) {
            errors += ValidationError("name", "Name is required")
        } else if (name.length > MAX_NAME_LENGTH) {
            errors += ValidationError("name", "Name must be $MAX_NAME_LENGTH characters or fewer")
        }

        val identifier = source.identifier.trim()
        if (identifier.isEmpty()) {
            errors += ValidationError("identifier", "Identifier is required")
        }

        if (Channel.wire(source.channel) == null) {
            errors += ValidationError("channel", "Channel must be notification or sms")
        }

        for (templateError in TemplateMatcher.templateErrors(source.template)) {
            errors += ValidationError("template", templateError)
        }

        if (source.incomeKeywords.keywordList().isEmpty()) {
            errors += ValidationError("incomeKeywords", "At least one income keyword is required")
        }
        if (source.expenseKeywords.keywordList().isEmpty()) {
            errors += ValidationError("expenseKeywords", "At least one expense keyword is required")
        }

        val conflict = existing.firstOrNull {
            it.id != source.id &&
                it.identifier.trim() == identifier &&
                it.channel.equals(source.channel, ignoreCase = true)
        }
        if (conflict != null) {
            errors += ValidationError(
                "identifier",
                "Identifier and channel are already used by \"${conflict.name}\"; " +
                    "edit or remove that source first",
            )
        }

        return errors
    }
}
package com.gomoney.capture.sync

import com.gomoney.capture.storage.ServerAccount
import com.gomoney.capture.storage.ServerAccountDao
import com.gomoney.capture.storage.ServerCategory
import com.gomoney.capture.storage.ServerCategoryDao
import com.gomoney.capture.storage.ServerConfiguration
import java.time.OffsetDateTime
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update

/**
 * Offline-tolerant cache of server accounts/categories (research R8, FR-014/016/
 * 021). Refresh replaces the cache atomically; a failed refresh keeps the last
 * known list and flags it unavailable so an existing binding is never silently
 * lost.
 */
class CatalogRepository(
    private val accountDao: ServerAccountDao,
    private val categoryDao: ServerCategoryDao,
    private val bridge: BridgeClient = BridgeClient(),
    private val clock: () -> OffsetDateTime = { OffsetDateTime.now() },
) {

    enum class Status { UNKNOWN, AVAILABLE, UNAVAILABLE }

    data class CatalogState(
        val accounts: Status = Status.UNKNOWN,
        val categories: Status = Status.UNKNOWN,
    )

    private val _state = MutableStateFlow(CatalogState())
    val state: StateFlow<CatalogState> = _state.asStateFlow()

    fun observeAccounts(): Flow<List<ServerAccount>> = accountDao.observeAll()

    fun observeCategories(): Flow<List<ServerCategory>> = categoryDao.observeAll()

    suspend fun accounts(): List<ServerAccount> = accountDao.all()

    suspend fun categories(): List<ServerCategory> = categoryDao.all()

    /** Refresh the account cache; returns false (and flags unavailable) on failure. */
    suspend fun refreshAccounts(config: ServerConfiguration): Boolean {
        val result = bridge.fetchAccounts(config)
        if (!result.ok) {
            _state.update { it.copy(accounts = Status.UNAVAILABLE) }
            return false
        }
        val now = clock().toString()
        accountDao.replaceAll(
            result.items.map {
                ServerAccount(
                    id = it.id,
                    label = it.label,
                    currency = it.currency,
                    type = it.type,
                    isDefault = it.isDefault,
                    refreshedAt = now,
                )
            },
        )
        _state.update { it.copy(accounts = Status.AVAILABLE) }
        return true
    }

    /** Refresh the category cache; returns false (and flags unavailable) on failure. */
    suspend fun refreshCategories(config: ServerConfiguration): Boolean {
        val result = bridge.fetchCategories(config)
        if (!result.ok) {
            _state.update { it.copy(categories = Status.UNAVAILABLE) }
            return false
        }
        val now = clock().toString()
        categoryDao.replaceAll(
            result.items.map { ServerCategory(id = it.id, label = it.label, refreshedAt = now) },
        )
        _state.update { it.copy(categories = Status.AVAILABLE) }
        return true
    }

    /** Instance convenience mirroring [Companion.isBindingStale]. */
    fun isBindingStale(boundAccountId: Int?, accounts: List<ServerAccount>): Boolean =
        Companion.isBindingStale(boundAccountId, accounts)

    companion object {
        /**
         * True when a source's bound account is no longer present in the
         * server list (deleted/renamed). A null binding is never stale
         * (spec edge case; data-model §1).
         */
        fun isBindingStale(boundAccountId: Int?, accounts: List<ServerAccount>): Boolean =
            boundAccountId != null && accounts.none { it.id == boundAccountId }
    }
}

