/**
 * Recent-events list (US1, T021): amount, bank, type, time, description and
 * delivery state per row — backed by real Room Flows so captured/delivery
 * state can be verified on-device. Rows are normalized transactions joined
 * with their delivery record; parse errors (no normalized transaction) are
 * shown with the sanitized error detail, never raw message text (FR-023).
 */
data class EventRow(
    val amountMinor: Long,
    val bank: String,
    val txAt: String,
    val state: String,
    val errorCategory: String?,
    val txId: String,
    val type: String = "expense",
    val description: String = "",
    val userMemo: String? = null,
    val memoSyncState: String = "synced",
)

class EventsViewModel(db: AppDatabase) : ViewModel() {

    data class EventsState(val rows: List<EventRow> = emptyList())

    val state: StateFlow<EventsState> = combine(
        db.normalizedTransactionDao().observeRecent(200),
        db.deliveryRecordDao().observeRecent(200),
        db.rawEventDao().observeAll(),
    ) { txs, deliveries, raws ->
        val deliveryById = deliveries.associateBy { it.id }
        val rawById = raws.associateBy { it.id }

        val txRows = txs.map { tx ->
            val delivery = deliveryById[tx.id]
            EventRow(
                amountMinor = tx.amountMinor,
                bank = tx.bank,
                txAt = tx.txAt,
                state = delivery?.state ?: "parsed",
                errorCategory = delivery?.errorCategory,
                txId = tx.id,
                type = tx.type,
                description = tx.description,
                userMemo = tx.userMemo,
                memoSyncState = tx.memoSyncState,
            )
        }
        // Parse-error rows: delivery record without a normalized transaction.
        val txIds = txs.map { it.id }.toSet()
        val errorRows = deliveries.filter { it.id !in txIds }.map { delivery ->
            val raw = rawById[delivery.sourceEventId]
            EventRow(
                amountMinor = 0,
                bank = raw?.sourcePackage ?: "unknown",
                txAt = raw?.postedAt ?: delivery.lastAttemptAt.orEmpty(),
                state = delivery.state,
                errorCategory = delivery.errorCategory ?: "parse_error",
                txId = delivery.id,
                description = delivery.errorDetail.orEmpty(),
            )
        }
        EventsState(rows = (txRows + errorRows).sortedByDescending { it.txAt })
    }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), EventsState())
}

@Composable
fun EventsScreen(
    state: EventsViewModel.EventsState,
    onRetry: (String) -> Unit = {},
    onClearProcessed: () -> Unit = {},
    onClearAll: () -> Unit = {},
    onSaveMemo: (String, String) -> Unit = { _, _ -> },
) {
    if (state.rows.isEmpty()) {
        Column(modifier = Modifier.fillMaxSize().padding(16.dp)) {
            Text("No captured transactions yet.", style = MaterialTheme.typography.bodyMedium)
        }
        return
    }
    var showClearAllDialog by remember { mutableStateOf(false) }
    if (showClearAllDialog) {
        AlertDialog(
            onDismissRequest = { showClearAllDialog = false },
            title = { Text("Clear all events?") },
            text = {
                Text(
                    "This permanently deletes every captured event, including queued and failed " +
                        "deliveries that have not reached Go Money. This cannot be undone.",
                )
            },
            confirmButton = {
                TextButton(onClick = {
                    showClearAllDialog = false
                    onClearAll()
                }) { Text("Clear all") }
            },
            dismissButton = {
                TextButton(onClick = { showClearAllDialog = false }) { Text("Cancel") }
            },
        )
    }
    LazyColumn(
        modifier = Modifier.fillMaxSize().padding(8.dp),
        verticalArrangement = Arrangement.spacedBy(8.dp),
    ) {
        item {
            Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                OutlinedButton(onClick = onClearProcessed) { Text("Clear processed") }
                OutlinedButton(onClick = { showClearAllDialog = true }) { Text("Clear all") }
            }
        }
        items(state.rows, key = { it.txId }) { row ->
            EventCard(row, onRetry, onSaveMemo)
        }
    }
}

@Composable
private fun EventCard(
    row: EventRow,
    onRetry: (String) -> Unit,
    onSaveMemo: (String, String) -> Unit,
) {
    var editingMemo by remember(row.txId) { mutableStateOf(false) }
    var memoDraft by remember(row.txId, row.userMemo) { mutableStateOf(row.userMemo.orEmpty()) }

    Card(modifier = Modifier.fillMaxWidth()) {
        Column(modifier = Modifier.padding(12.dp)) {
            Row(modifier = Modifier.fillMaxWidth()) {
                Text(
                    text = if (row.amountMinor == 0L) "—" else "${row.amountMinor} IRR",
                    style = MaterialTheme.typography.titleMedium,
                    modifier = Modifier.weight(1f),
                )
                Text(text = row.state.uppercase(), style = MaterialTheme.typography.labelMedium)
            }
            Text(text = "${row.bank} · ${row.type}", style = MaterialTheme.typography.bodySmall)
            if (row.description.isNotBlank()) {
                Text(text = row.description, style = MaterialTheme.typography.bodySmall, maxLines = 2)
            }
            Text(text = formatTime(row.txAt), style = MaterialTheme.typography.bodySmall)
            row.errorCategory?.let {
                Text(text = "category: $it", style = MaterialTheme.typography.labelSmall)
            }

            if (row.amountMinor > 0L) {
                if (!row.userMemo.isNullOrBlank()) {
                    Text("Note: ${row.userMemo}", style = MaterialTheme.typography.bodyMedium)
                }
                if (row.memoSyncState == "pending") {
                    val pendingLabel = if (row.userMemo.isNullOrBlank()) {
                        "Note removal saved on this phone · waiting to sync"
                    } else {
                        "Saved on this phone · waiting to sync"
                    }
                    Text(pendingLabel, style = MaterialTheme.typography.labelSmall)
                }
                if (editingMemo) {
                    OutlinedTextField(
                        value = memoDraft,
                        onValueChange = { if (it.length <= MAX_MEMO_LENGTH) memoDraft = it },
                        label = { Text("What was this for?") },
                        placeholder = { Text("e.g. groceries, lunch, taxi") },
                        modifier = Modifier.fillMaxWidth(),
                        supportingText = { Text("Saved on this phone and synced to Go Money · ${memoDraft.length}/$MAX_MEMO_LENGTH") },
                    )
                    Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                        Button(onClick = {
                            onSaveMemo(row.txId, memoDraft)
                            editingMemo = false
                        }) {
                            Text("Save note")
                        }
                        OutlinedButton(onClick = { editingMemo = false }) {
                            Text("Cancel")
                        }
                    }
                } else {
                    OutlinedButton(onClick = { editingMemo = true }) {
                        Text(if (row.userMemo.isNullOrBlank()) "Add note" else "Edit note")
                    }
                }
            }

            if (row.state == "failed") {
                OutlinedButton(onClick = { onRetry(row.txId) }) {
                    Text("Retry delivery")
                }
            }
        }
    }
}

private const val MAX_MEMO_LENGTH = 200

private fun formatTime(txAt: String): String = runCatching {
    OffsetDateTime.parse(txAt).format(DateTimeFormatter.ofPattern("MM-dd HH:mm"))
}.getOrDefault(txAt)
package com.gomoney.capture.ui

import com.gomoney.capture.sync.SyncEngine
import com.gomoney.capture.storage.AppDatabase
import com.gomoney.capture.storage.DeliveryRepository
import com.gomoney.capture.storage.MaintenanceRepository
import com.gomoney.capture.storage.SettingsRepository

/**
 * Event actions (US4, T040, FR-022): manual retry requeues FAILED → QUEUED
 * and triggers an expedited sync (US2.4); clear removes ONLY sent/terminal
 * rows, preserving pending/failed (spec edge case).
 */
class EventActions(
    private val context: android.content.Context,
    private val db: AppDatabase,
) {

    private val deliveryRepository = DeliveryRepository(db.deliveryRecordDao())
    private val maintenance = MaintenanceRepository(
        rawEventDao = db.rawEventDao(),
    )

    /** Manual retry: FAILED → QUEUED, then expedited sync. */
    suspend fun retry(deliveryId: String): Boolean {
        val requeued = deliveryRepository.requeue(deliveryId) ?: return false
        SyncEngine.enqueueExpedited(context)
        return requeued.state == "queued"
    }

    /** Save a private note locally first, then sync it to the bridge/Go Money. */
    suspend fun saveMemo(transactionId: String, memo: String): Boolean {
        val normalizedMemo = memo.trim().take(MAX_MEMO_LENGTH).ifBlank { null }
        val current = db.normalizedTransactionDao().byId(transactionId) ?: return false
        if (current.userMemo == normalizedMemo && current.memoSyncState == "synced") return true
        if (db.normalizedTransactionDao().updateMemo(transactionId, normalizedMemo) == 0) return false
        SyncEngine.enqueueExpedited(context)
        return true
    }

    /**
     * Set/change a captured transaction's destination account and category
     * (US3, FR-017/018/019/020): persist locally first, mark pending, then
     * trigger an expedited sync so it reaches the same Go Money transaction.
     */
    suspend fun saveAssignment(transactionId: String, destinationAccountId: Int?, categoryId: Int?): Boolean {
        val current = db.normalizedTransactionDao().byId(transactionId) ?: return false
        if (current.destinationAccountId == destinationAccountId &&
            current.categoryId == categoryId &&
            current.assignmentSyncState == "synced"
        ) {
            return true
        }
        if (db.normalizedTransactionDao().updateAssignment(transactionId, destinationAccountId, categoryId) == 0) {
            return false
        }
        SyncEngine.enqueueExpedited(context)
        return true
    }

    /** Clear processed (sent/terminal) rows; pending/failed preserved. */
    suspend fun clearProcessed(): Int = maintenance.clearProcessed()

    /** Clear all rows, including queued and failed items (requires user confirmation in the UI). */
    suspend fun clearAll(): Int = maintenance.clearAll()

    private companion object {
        const val MAX_MEMO_LENGTH = 200
    }
}

package com.gomoney.capture.capture

import android.app.Notification
import android.service.notification.NotificationListenerService
import android.service.notification.StatusBarNotification
import com.gomoney.capture.storage.AppDatabase
import com.gomoney.capture.storage.DedupRepository
import com.gomoney.capture.storage.DeliveryRepository
import com.gomoney.capture.storage.RawEvent
import com.gomoney.capture.storage.SettingsRepository
import com.gomoney.capture.sync.MemoPromptNotifier
import java.time.OffsetDateTime
import java.util.UUID
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch

/**
 * Notification capture (US1, T019, FR-001/002/003): filters by the
 * ServerConfiguration.enabledBankPackages allow-list, ignores all other
 * apps, and writes a RawEvent to Room BEFORE any processing.
 */
class NotificationCaptureService : android.service.notification.NotificationListenerService() {

    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    private lateinit var pipeline: CapturePipeline
    private lateinit var gate: CaptureGate

    override fun onCreate() {
        super.onCreate()
        val context = applicationContext
        val settings = SettingsRepository(context)
        val db = AppDatabase.get(context)
        pipeline = CapturePipeline(
            db = db,
            settings = settings,
            deliveryRepository = DeliveryRepository(db.deliveryRecordDao()),
            dedupRepository = DedupRepository(db.dedupCacheDao()),
            onCaptured = { tx ->
                TransactionSyncHelper.enqueueExpedited(context)
                MemoPromptNotifier.show(context, tx)
            },
        )
        gate = CaptureGate(PlatformCapturePermission(context))
    }

    override fun onNotificationPosted(sbn: StatusBarNotification) {
        val pkg = sbn.packageName ?: return

        // FR-001: only allow-listed packages are even considered; everything
        // else is ignored without persisting anything.
        val text = extractText(sbn) ?: return
        // Use the notification's own postTime (epoch millis) as the event
        // timestamp — safer than capture-time wall clock when delivery is
        // delayed; fall back to now() when postTime is missing/implausible.
        val postedAt = safePostedAt(sbn.postTime)

        // Permission gate: revoked access stops capture; queued data is
        // preserved (edge case).
        if (!gate.allowsNotificationCapture()) return

        scope.launch {
            pipeline.process(
                RawEvent(
                    id = UUID.randomUUID().toString(),
                    source = "notification",
                    sourcePackage = pkg,
                    bank = null,
                    title = sbn.notification.extras.getCharSequence(android.app.Notification.EXTRA_TITLE)?.toString(),
                    text = text,
                    postedAt = postedAt,
                    capturedAt = OffsetDateTime.now().toString(),
                ),
            )
        }
    }

    /**
     * BigText-aware extraction: some banks (e.g. Blue) post a short
     * EXTRA_TEXT and the full message in EXTRA_BIG_TEXT. Taking only the
     * first would lose the transaction label/amount, so the longer non-blank
     * variant wins. No raw text is ever logged here (FR-028).
     */
    private fun extractText(sbn: StatusBarNotification): String? {
        val extras = sbn.notification.extras
        val text = extras.getCharSequence(android.app.Notification.EXTRA_TEXT)?.toString()
        val bigText = extras.getCharSequence(android.app.Notification.EXTRA_BIG_TEXT)?.toString()
        return listOf(text, bigText)
            .filterNotNull()
            .filter { it.isNotBlank() }
            .maxByOrNull { it.length }
    }

    private fun safePostedAt(postTime: Long): String {
        if (postTime > 0) {
            return runCatching {
                OffsetDateTime.ofInstant(java.time.Instant.ofEpochMilli(postTime), java.time.ZoneId.systemDefault())
                    .toString()
            }.getOrDefault(OffsetDateTime.now().toString())
        }
        return OffsetDateTime.now().toString()
    }
}
