```kotlin
override fun onCreate() {
    super.onCreate()
    SyncEngine.enqueuePeriodic(this)
    CoroutineScope(SupervisorJob() + Dispatchers.IO).launch {
        runCatching {
            val db = AppDatabase.get(this@CaptureApplication)
            com.gomoney.capture.source.TransactionSourceRepository(db.transactionSourceDao(), db.parseErrorDao(), db).seedDefaults()
        }
    }
}
```

Also, seeding could live in TransactionSyncWorker too, but app startup is fine.

