		txn := validTxn(fingerprintHex(byte(100 + i)))
		txn.Currency = currency
		res := bridgePost(t, ts.URL+"/v1/transactions", "test-token", marshal(t, txn))
		require.Equal(t, http.StatusBadRequest, res.StatusCode, "currency %q", currency)
